/*!
 * Themeasy — Admin Nav Menus
 *
 * Handles admin-side enhancements for WordPress navigation menus
 * and the Megamenu custom post type.
 *
 * - Auto-selects "Elementor Canvas" template for megamenu posts
 * - Adds SVG icon picker to menu items via wp.media
 *
 * @author Themeasy
 * @link https://themeasy.co
 * @since 1.0.0
 */

(function (document) {
  'use strict'

  // ------------------------------------------------------------------------
  // Utils
  // ------------------------------------------------------------------------
  function onDomReady(fn) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', fn, { once: true })
      return
    }
    fn()
  }

  // ------------------------------------------------------------------------
  // Megamenu — auto-select Elementor Canvas template
  // ------------------------------------------------------------------------
  function selectCanvasTemplate() {
    const option = document.querySelector(
      '.post-type-themeasy-megamenu option[value="elementor_canvas"]',
    )
    if (option) {
      option.selected = true
    }
  }

  // ------------------------------------------------------------------------
  // Menu Icon Picker
  // ------------------------------------------------------------------------

  /**
   * Open the WP Media modal filtered to images and handle SVG selection.
   *
   * @param {HTMLElement} button  The `.themeasy-menu-icon__select` button.
   * @param {Event}       event   The click event.
   */
  function handleIconSelect(button, event) {
    event.preventDefault()

    const wrapper = button.closest('.themeasy-menu-icon')
    const itemId = button.dataset.itemId

    const frame = wp.media({
      title: 'Select SVG File',
      library: { type: 'image' },
      button: { text: 'Use this icon' },
      multiple: false,
    })

    frame.on('select', function () {
      const attachment = frame.state().get('selection').first().toJSON()

      if (attachment.mime !== 'image/svg+xml') {
        alert('Please select an SVG file.')
        return
      }

      // Save attachment ID to the hidden input.
      const input = document.getElementById('edit-menu-item-icon-' + itemId)
      if (input) {
        input.value = attachment.id
      }

      // Render icon preview.
      const preview = wrapper.querySelector('.themeasy-menu-icon__preview')
      if (preview) {
        preview.innerHTML = ''
        const img = document.createElement('img')
        img.src = attachment.url
        img.style.height = '30px'
        img.style.marginLeft = '5px'
        preview.appendChild(img)
      }

      // Show the remove button.
      const removeBtn = wrapper.querySelector('.themeasy-menu-icon__remove')
      if (removeBtn) {
        removeBtn.style.display = ''
      }
    })

    frame.open()
  }

  /**
   * Clear the icon selection for a menu item.
   *
   * @param {HTMLElement} button  The `.themeasy-menu-icon__remove` button.
   * @param {Event}       event   The click event.
   */
  function handleIconRemove(button, event) {
    event.preventDefault()

    const wrapper = button.closest('.themeasy-menu-icon')
    const itemId = button.dataset.itemId

    // Clear the hidden input.
    const input = document.getElementById('edit-menu-item-icon-' + itemId)
    if (input) {
      input.value = ''
    }

    // Clear the preview.
    const preview = wrapper.querySelector('.themeasy-menu-icon__preview')
    if (preview) {
      preview.innerHTML = ''
    }

    // Hide the remove button.
    button.style.display = 'none'
  }

  /**
   * Bind click handlers to all icon select/remove buttons.
   */
  function initIconPickers() {
    if (typeof wp === 'undefined' || typeof wp.media !== 'function') return

    document
      .querySelectorAll('.themeasy-menu-icon__select')
      .forEach(function (button) {
        button.addEventListener('click', function (event) {
          handleIconSelect(button, event)
        })
      })

    document
      .querySelectorAll('.themeasy-menu-icon__remove')
      .forEach(function (button) {
        button.addEventListener('click', function (event) {
          handleIconRemove(button, event)
        })
      })
  }

  // ------------------------------------------------------------------------
  // Boot
  // ------------------------------------------------------------------------
  onDomReady(function () {
    selectCanvasTemplate()
    initIconPickers()
  })

})(document)
